CREATE TABLE "memory_circles" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "owner_user_id" INTEGER CHECK ("owner_user_id" IS NULL OR "owner_user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "circle_name" TEXT DEFAULT 'My Memory Circle',
  "invite_code" TEXT UNIQUE,
  "invite_code_expires" TEXT,
  "max_members" INTEGER DEFAULT 10 CHECK ("max_members" IS NULL OR "max_members" BETWEEN -2147483648 AND 2147483647),
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "memory_circle_members" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "circle_id" INTEGER CHECK ("circle_id" IS NULL OR "circle_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "memory_circles"("id") ON DELETE CASCADE,
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "role" TEXT NOT NULL DEFAULT 'helper',
  "display_name" TEXT,
  "joined_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "last_active_at" TEXT,
  UNIQUE ("circle_id", "user_id")
) STRICT;

CREATE TABLE "family_prompts" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "circle_id" INTEGER CHECK ("circle_id" IS NULL OR "circle_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "memory_circles"("id") ON DELETE CASCADE,
  "from_user_id" INTEGER CHECK ("from_user_id" IS NULL OR "from_user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE SET NULL,
  "for_user_id" INTEGER CHECK ("for_user_id" IS NULL OR "for_user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "prompt_text" TEXT NOT NULL,
  "prompt_note" TEXT,
  "status" TEXT DEFAULT 'pending',
  "answered_story_id" INTEGER CHECK ("answered_story_id" IS NULL OR "answered_story_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "stories"("id") ON DELETE NO ACTION,
  "answered_at" TEXT,
  "declined_at" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "family_encouragements" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "circle_id" INTEGER CHECK ("circle_id" IS NULL OR "circle_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "memory_circles"("id") ON DELETE CASCADE,
  "from_user_id" INTEGER CHECK ("from_user_id" IS NULL OR "from_user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE SET NULL,
  "for_user_id" INTEGER CHECK ("for_user_id" IS NULL OR "for_user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "encouragement_type" TEXT DEFAULT 'heart',
  "message" TEXT,
  "related_story_id" INTEGER CHECK ("related_story_id" IS NULL OR "related_story_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "stories"("id") ON DELETE NO ACTION,
  "seen_by_recipient" INTEGER DEFAULT 0 CHECK ("seen_by_recipient" IS NULL OR "seen_by_recipient" IN (0, 1)),
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "streak_history" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "date" TEXT NOT NULL,
  "had_activity" INTEGER DEFAULT 0 CHECK ("had_activity" IS NULL OR "had_activity" IN (0, 1)),
  "streak_on_this_day" INTEGER DEFAULT 0 CHECK ("streak_on_this_day" IS NULL OR "streak_on_this_day" BETWEEN -2147483648 AND 2147483647),
  "shield_used" INTEGER DEFAULT 0 CHECK ("shield_used" IS NULL OR "shield_used" IN (0, 1)),
  "prompt_completed" INTEGER DEFAULT 0 CHECK ("prompt_completed" IS NULL OR "prompt_completed" IN (0, 1)),
  UNIQUE ("user_id", "date")
) STRICT;

CREATE TABLE "notification_queue" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "notification_type" TEXT NOT NULL,
  "channel" TEXT NOT NULL,
  "subject" TEXT,
  "body" TEXT NOT NULL,
  "data" TEXT DEFAULT '{}' CHECK ("data" IS NULL OR json_valid("data")),
  "scheduled_for" TEXT NOT NULL,
  "sent_at" TEXT,
  "failed_at" TEXT,
  "failure_reason" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "newsletter_subscribers" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "email" TEXT NOT NULL UNIQUE,
  "subscribed_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "unsubscribed_at" TEXT,
  "source" TEXT DEFAULT 'blog',
  "ip_address" TEXT,
  "user_agent" TEXT
) STRICT;

CREATE TABLE "password_reset_tokens" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "token_hash" TEXT NOT NULL,
  "expires_at" TEXT NOT NULL,
  "used_at" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "email_verification_tokens" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "token_hash" TEXT NOT NULL,
  "expires_at" TEXT NOT NULL,
  "used_at" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "email_session_tokens" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "token_hash" TEXT NOT NULL,
  "prompt_text" TEXT NOT NULL,
  "prompt_chapter_id" TEXT,
  "prompt_question_id" TEXT,
  "expires_at" TEXT NOT NULL,
  "used_at" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "memos" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "title" TEXT,
  "audio_url" TEXT NOT NULL,
  "transcript" TEXT,
  "duration" INTEGER CHECK ("duration" IS NULL OR "duration" BETWEEN -2147483648 AND 2147483647),
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "free_stories" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "title" TEXT,
  "content" TEXT NOT NULL,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "telnyx_calls" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "call_control_id" TEXT,
  "stream_id" TEXT,
  "call_status" TEXT DEFAULT 'initiated',
  "prompt_text" TEXT,
  "prompt_chapter_id" TEXT,
  "prompt_question_id" TEXT,
  "duration_seconds" INTEGER CHECK ("duration_seconds" IS NULL OR "duration_seconds" BETWEEN -2147483648 AND 2147483647),
  "transcript_saved" INTEGER DEFAULT 0 CHECK ("transcript_saved" IS NULL OR "transcript_saved" IN (0, 1)),
  "error_message" TEXT,
  "started_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "answered_at" TEXT,
  "ended_at" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "ai_usage" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "date" TEXT NOT NULL DEFAULT CURRENT_DATE,
  "request_count" INTEGER DEFAULT 0 CHECK ("request_count" IS NULL OR "request_count" BETWEEN -2147483648 AND 2147483647),
  "token_count" INTEGER DEFAULT 0 CHECK ("token_count" IS NULL OR "token_count" BETWEEN -2147483648 AND 2147483647),
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  UNIQUE ("user_id", "date")
) STRICT;

CREATE TABLE "refund_requests" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "payment_id" INTEGER CHECK ("payment_id" IS NULL OR "payment_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "payments"("id") ON DELETE CASCADE,
  "type" TEXT NOT NULL,
  "reason" TEXT,
  "amount" INTEGER CHECK ("amount" IS NULL OR "amount" BETWEEN -2147483648 AND 2147483647),
  "status" TEXT DEFAULT 'pending',
  "admin_notes" TEXT,
  "resolved_at" TEXT,
  "stripe_refund_id" TEXT,
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "lulu_orders" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT CHECK ("id" IS NULL OR "id" BETWEEN -2147483648 AND 2147483647),
  "user_id" INTEGER NOT NULL CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "lulu_order_id" TEXT NOT NULL UNIQUE,
  "status" TEXT DEFAULT 'created',
  "created_at" TEXT DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TABLE "token_blacklist" (
  "jti" TEXT PRIMARY KEY NOT NULL CHECK ("jti" IS NULL OR length("jti") <= 255),
  "user_id" INTEGER NOT NULL CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647),
  "expires_at" TEXT NOT NULL,
  "revoked_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f+00', 'now'))
) STRICT;

CREATE TABLE "user_token_invalidation" (
  "user_id" INTEGER PRIMARY KEY NOT NULL CHECK ("user_id" IS NULL OR "user_id" BETWEEN -2147483648 AND 2147483647) REFERENCES "users"("id") ON DELETE CASCADE,
  "invalidated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f+00', 'now'))
) STRICT;

CREATE TABLE "cron_health" (
  "job_name" TEXT PRIMARY KEY NOT NULL CHECK ("job_name" IS NULL OR length("job_name") <= 100),
  "last_success" TEXT,
  "last_attempt" TEXT
) STRICT;

CREATE TABLE "schema_migrations" (
  "version" TEXT PRIMARY KEY NOT NULL CHECK ("version" IS NULL OR length("version") <= 255),
  "applied_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f+00', 'now'))
) STRICT;

